sys_script_client.script:
function onLoad() {
    // Check if the 'task_type' field value is 'Maker Review'. If not, exit the function.
    if (g_form.getValue('task_type') !== 'Maker Review')
        return;

    // Parse the URL parameters to check for the 'discard_option' query parameter.
    var url = new URL(top.location.href);
    //var param = new URLSearchParams(url.search).get('discard_option');
    var test = g_form.getValue('event_status');
    g_form.addInfoMessage("event =" + test);

    if (test == 'REVIEW_COMPLETED.DISCARD') {
        g_form.setDisplay('discard_reason', true);
        g_form.removeOption('discard_reason', '');
        g_form.addInfoMessage("test 2");
        if (!g_form.getValue('discard_reason')) {
            g_form.addInfoMessage("test3");
            g_form.setValue('discard_reason', 'pick_rsn', 'Please select reason for discarding'); //set value 'Please select reason for discarding'
			g_form.setMandatory('discard_reason', true);
            g_form.save();
            g_form.reload();
        }

        // Check if the 'index_queue_multiple' field contains multiple instructions (comma-separated values).
        var isMultiInstruction = g_form.getValue('index_queue_multiple').includes(',');

        if (isMultiInstruction)
            g_form.addOption('discard_reason', 'mix_inst', 'Incorrectly Indexed as Multi Instruction');
        else
            g_form.removeOption('discard_reason', 'mix_inst');

    } else
        g_form.addInfoMessage("Test 9");
    g_form.setDisplay('discard_reason', false);

}
